#include "platform/native_canonical_drivers_roster.h"
#include <string.h>
static int List(const struct NativeCanonicalDriversRosterInput*i,const uint8_t*in,uint8_t count,uint8_t max,uint8_t*out,uint32_t*global,int botsOnly){uint32_t seen=0;if(count>max)return 0;for(uint8_t n=0;n<max;n++){uint8_t h=in[n];if(n>=count){if(h!=NATIVE_CANONICAL_DRIVERS_HANDLE_NONE)return 0;out[n]=h;continue;}if(h>=8||!i->slots[h].present||(botsOnly&&i->slots[h].kind!=NATIVE_CANONICAL_DRIVER_KIND_BOT)||(seen&(1u<<h))||(global&&(*global&(1u<<h))))return 0;seen|=1u<<h;if(global)*global|=1u<<h;out[n]=h;}return 1;}
static int Winners(const struct NativeCanonicalDriversRosterInput*i,uint8_t*out){uint32_t seen=0;for(uint8_t n=0;n<4;n++){uint8_t id=i->winnerDriverIDs[n],slot=0;if(n>=i->winnerCount){if(id!=NATIVE_CANONICAL_DRIVERS_HANDLE_NONE)return 0;out[n]=id;continue;}for(;slot<8;slot++)if(i->slots[slot].present&&i->slots[slot].driverID==id)break;if(slot==8||(seen&(1u<<slot)))return 0;seen|=1u<<slot;out[n]=slot;}return 1;}
int NativeCanonicalDriversRoster_Normalize(const struct NativeCanonicalDriversRosterInput*i,struct NativeCanonicalDriversRosterCandidate*out){struct NativeCanonicalDriversRosterCandidate c;uint8_t human=0,bot=0;uint32_t navSeen=0,botMask=0;if(!i||!out||i->numLaps<0)return 0;memset(&c,0,sizeof(c));c.prelude.slotCount=8;c.prelude.detailedVersion=1;c.prelude.numLaps=i->numLaps;memset(c.prelude.raceOrder,0xff,8);memset(c.prelude.winnerSlots,0xff,4);memset(c.prelude.humanPlayerPositions,0xff,8);memset(c.prelude.navListOrder,0xff,24);for(uint8_t n=0;n<8;n++){const struct NativeCanonicalDriversRosterSlot*s=&i->slots[n];if(!s->present)continue;if(s->present!=1||s->driverID!=n||!NativeCanonicalDriverBehavior_ValidateKind(s->kind,s->behaviorID,s->threadBehaviorID))return 0;c.prelude.presenceMask|=1u<<n;c.behaviorID[n]=s->behaviorID;c.threadBehaviorID[n]=s->threadBehaviorID;c.kind[n]=s->kind;if(s->kind==NATIVE_CANONICAL_DRIVER_KIND_HUMAN)human++;else {bot++;botMask|=1u<<n;}}if(i->playerCount!=human||i->raceOrderCount>8||i->winnerCount>4)return 0;c.prelude.raceOrderCount=i->raceOrderCount;c.prelude.winnerCount=i->winnerCount;c.prelude.playerCount=human;c.prelude.activeBotCount=bot;if(!List(i,i->raceOrder,i->raceOrderCount,8,c.prelude.raceOrder,NULL,0)||!Winners(i,c.prelude.winnerSlots))return 0;for(uint8_t n=0;n<8;n++){if(n<human){if(i->ranks[n]>7)return 0;c.prelude.humanPlayerPositions[n]=i->ranks[n];}else if(i->ranks[n]!=NATIVE_CANONICAL_DRIVERS_HANDLE_NONE)return 0;}for(uint8_t n=0;n<3;n++){c.prelude.navListCount[n]=i->navCount[n];if(!List(i,i->navOrder[n],i->navCount[n],8,c.prelude.navListOrder[n],&navSeen,1))return 0;}if(navSeen!=botMask)return 0;*out=c;return 1;}
